"python3 -c '
from check import load_input
from collections import defaultdict
chats, messages, seed, answers = load_input("data/dev")

# Messages by person
p_msgs = defaultdict(list)
for m in messages:
    p_msgs[m["sender_id"]].append(m)

# DMs for each person
p_dms = {}
for c in chats:
    if not c["is_group"]:
        other = next(p for p in c["participants"] if p != "ME")
        p_dms[other] = c

# Groups for each person
p_groups = defaultdict(list)
for c in chats:
    if c["is_group"]:
        for p in c["participants"]:
            if p != "ME":
                p_groups[p].append(c["name"])

for p in sorted(answers["people"], key=lambda x: (x["circle"], x["id"])):
    pid = p["id"]
    circle = p["circle"]
    dm = p_dms.get(pid)
    dm_name = dm["name"] if dm else "NO DM"
    num_m = len(p_msgs[pid])
    groups = p_groups[pid][:3]
    print(f"[{circle:<9}] {pid:<5} | DM: {dm_name:<25} | msgs: {num_m:<3} | Groups: {groups}")
'"

